/* C API of the Rust port of `bcd.c`, generated by rust-anything. */
#ifndef BCD_RS_H
#define BCD_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

unsigned _bcd2bin(unsigned char val);
unsigned char _bin2bcd(unsigned val);

/* The same functions under `rust_anything_` names, for shadow runs. */
unsigned rust_anything__bcd2bin(unsigned char val);
unsigned char rust_anything__bin2bcd(unsigned val);

#endif /* BCD_RS_H */
